// Which sign-in the CMS uses.
//
// This file is the swap point, as it always has been: every screen, guard and
// plugin imports its auth from here and nothing imports Openbase or Supabase
// directly. Supabase wins when its project is configured — see
// modules/supabase/enabled.ts — and Openbase is what everything falls back to
// otherwise.
//
// The two expose the same functions with the same signatures, so nothing below
// this import block changed when Supabase was added.

import { useEffect, useState } from "react";
import * as openbaseAuth from "../modules/openbase/openbase";
import * as supabaseAuth from "../modules/supabase/auth";
import { usingSupabase } from "../modules/supabase/enabled";

const auth = usingSupabase() ? supabaseAuth : openbaseAuth;

const {
  login,
  logout,
  signup,
  getMe,
  getToken,
  requestPasswordReset,
  resetPassword,
  authedRequest,
  isLoggedIn,
  initAuth,
} = auth;

/* ============================================================
   DIRECT AUTH API
   Non-React modules can import these directly.
   ============================================================ */

export {
  login,
  logout,
  signup,
  getMe,
  getToken,
  requestPasswordReset,
  resetPassword,
  authedRequest,
  isLoggedIn,
  initAuth,
};

/* ============================================================
   REACT AUTH API
   ============================================================ */

export type CmsAuthState = {
  loading: boolean;
  authenticated: boolean;

  login: typeof login;
  logout: typeof logout;
  signup: typeof signup;

  getMe: typeof getMe;
  getToken: typeof getToken;

  requestPasswordReset: typeof requestPasswordReset;
  resetPassword: typeof resetPassword;

  authedRequest: typeof authedRequest;
  isLoggedIn: typeof isLoggedIn;
  initAuth: typeof initAuth;
};

/**
 * Verifies the stored session once, on mount.
 *
 * This used to be `useOpenbase()`, which called Openbase's own initAuth
 * directly. That was fine while there was one backend and wrong the moment
 * there were two: with Supabase selected, the hook would have asked Openbase
 * whether the user was signed in, been told no, and left the CMS permanently
 * on the login screen. It calls the SELECTED initAuth instead.
 */
function useSession(): { loading: boolean; authenticated: boolean } {
  const [loading, setLoading] = useState(true);
  const [authenticated, setAuthenticated] = useState(false);

  useEffect(() => {
    let mounted = true;

    (async () => {
      try {
        const ok = await initAuth();
        if (mounted) setAuthenticated(Boolean(ok));
      } catch {
        if (mounted) setAuthenticated(false);
      } finally {
        if (mounted) setLoading(false);
      }
    })();

    return () => {
      mounted = false;
    };
  }, []);

  return { loading, authenticated };
}

export function useAuth(): CmsAuthState {
  const { loading, authenticated } = useSession();

  return {
    loading,
    authenticated,

    login,
    logout,
    signup,

    getMe,
    getToken,

    requestPasswordReset,
    resetPassword,

    authedRequest,
    isLoggedIn,
    initAuth,
  };
}