
import validTokenForwardToApp from "../../../toggles/valid-token--forward-to-app";
import React, { useState, useEffect } from "react";
import { navigate } from "gatsby";
import { FaUser, FaLock, FaEye, FaEyeSlash, FaExclamationTriangle, FaImage, FaClipboardList, FaBolt, FaArrowRight } from "react-icons/fa";


import theme from "../../../config/opencms--theme";
import { useAuth } from "../../../config/opencms--useAuth";
import { BRANDING } from "../../../config/opencms--branding";

// Mirror of the helper in CmsShell — kept inline so this page has no
// dependency on the dashboard component.
function withAlpha(color: string, alpha: number): string {
  if (color.startsWith("#") && (color.length === 4 || color.length === 7)) {
    const hex = color.length === 4
      ? color.slice(1).split("").map(c => c + c).join("")
      : color.slice(1);
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return `rgba(${r},${g},${b},${alpha})`;
  }
  return color;
}
export const OpenCmsLogin: React.FC = () => {
  /* Empty, always.
     These used to be seeded from config/profile--credentials.secret.ts as a
     convenience. That file is compiled into the JavaScript this page serves,
     so the convenience was a real account's password sitting in the page
     source of a public website - readable by anyone who opened DevTools, and
     visible in the password field the moment they clicked the eye icon.
     A login form has no business knowing a password before it is typed. */
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);
  const [shake, setShake] = useState(false);
  const [entered, setEntered] = useState(false);

  const {
    loading: authLoading,
    authenticated,
    login,
  } = useAuth();

  /* The entrance animation belongs to the first paint and nothing else.
     Without this the card reads `fadeUp` again the moment a shake finishes,
     so a wrong password made the whole panel fade in from nothing and slide
     up - which looks exactly like the page reloading and losing its state.
     Nothing was reloading; the animation was simply being redeclared. */
  useEffect(() => {
    const timer = setTimeout(() => setEntered(true), 500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (
      validTokenForwardToApp &&
      !authLoading &&
      authenticated
    ) {
      navigate("/dashboard", { replace: true });
    }
  }, [authLoading, authenticated]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    setLoading(true);
    setErr("");

    try {
      await login(email.trim(), pass);

      if (validTokenForwardToApp) {
        navigate("/dashboard", { replace: true });
      }
    } catch (err: any) {
      const msg =
        err?.data?.error ||
        err?.data?.message ||
        (typeof err?.data === "string" ? err.data : "") ||
        err?.message ||
        "Invalid email or password.";

      setErr(msg);
      setShake(true);
      setTimeout(() => setShake(false), 500);
      setLoading(false);
    }
  };

  return (
    <div style={s.page} className="kr-login">
      <style>{css}</style>

      {/* Left panel */}
      <div style={s.left} className="kr-login__left">
        <div style={s.leftInner}>
          <h1 style={s.leftTitle}>{BRANDING.name}<br />{BRANDING.tagline}</h1>
          <p style={s.leftSub}>Manage your website content, images, and more — all in one place.</p>
          <div style={s.features}>
            {([
              [<FaImage />, "Image Gallery Management"],
              [<FaClipboardList />, "Content Updates"],
              [<FaBolt />, "Fast & Secure Access"],
            ] as [React.ReactNode, string][]).map(([icon, label]) => (
              <div key={label} style={s.feature}>
                <span style={s.featureIcon}>{icon}</span>
                {label}
              </div>
            ))}
          </div>
        </div>
        <div style={s.brandShape} />
      </div>

      {/* Right panel */}
      <div style={s.right} className="kr-login__right">
        <div className="kr-login__card" style={{ ...s.card, animation: shake
              ? "shake 0.4s ease"
              /* "none" once the entrance has played. fadeUp ends at opacity 1
                 and no offset, which is the card own resting style, so
                 dropping the animation changes nothing visually. */
              : entered
                ? "none"
                : "fadeUp 0.5s ease both",
          }}
        >
          {BRANDING.logo ? (
            <img src={BRANDING.logo} alt={BRANDING.name} style={s.logo} />
          ) : (
            <div style={s.logoFallback}>{BRANDING.shortName || "CMS"}</div>
          )}
          <h2 style={s.title}>Welcome back</h2>
          <p style={s.subtitle}>{BRANDING.cardSubtitle}</p>

          <form onSubmit={handleSubmit} style={s.form}>
            {/* Email */}
            <div style={s.fieldWrap}>
              <span style={s.fieldIcon}><FaUser size={14} /></span>
              <input
                style={s.input}
                type="email"
                placeholder="Email"
                value={email}
                onChange={e => { setEmail(e.target.value); setErr(""); }}
                required
                autoComplete="email"
              />
            </div>

            {/* Password */}
            <div style={s.fieldWrap}>
              <span style={s.fieldIcon}><FaLock size={14} /></span>
              <input
                style={{ ...s.input, paddingRight: 44 }}
                type={showPass ? "text" : "password"}
                placeholder="Password"
                value={pass}
                onChange={e => { setPass(e.target.value); setErr(""); }}
                required
                autoComplete="current-password"
              />
              <button
                type="button"
                style={s.eyeBtn}
                onClick={() => setShowPass(p => !p)}
                tabIndex={-1}
              >
                {showPass ? <FaEyeSlash size={15} /> : <FaEye size={15} />}
              </button>
            </div>

            {err && (
              <div style={s.errBox}>
                <FaExclamationTriangle size={13} /> {err}
              </div>
            )}

            <button style={{ ...s.btn, opacity: loading ? 0.75 : 1 }} type="submit" disabled={loading}>
              {loading ? <span style={s.spinner} className="spin" /> : null}
              {loading ? "Signing in…" : <><span>Sign In</span><FaArrowRight size={13} /></>}
            </button>
          </form>

          <p style={s.hint}>Need access? Contact your admin.</p>
        </div>
      </div>
    </div>
  );
};

