const css = `
/* == mobile ==============================================
   The two-panel layout is a desktop idea. On a phone the right-hand column
   asked for 380px of a 390px screen, which left the brand panel about ninety
   pixels wide and broke its heading to one word per line.

   Below 860px the brand panel is removed rather than stacked. Somebody
   opening this page wants to sign in; the marketing copy beside the form is
   for the wide screen where it costs nothing, and stacking it would just push
   the form below the fold on the device where that matters most. The CMS logo
   on the card carries the branding.

   !important throughout because these elements carry inline styles, which a
   stylesheet cannot otherwise override. */
@media (max-width: 860px) {
  .kr-login__left { display: none !important; }
  .kr-login__right {
    width: 100% !important;
    min-width: 0 !important;
    padding: 28px 18px !important;
  }
}

@media (max-width: 420px) {
  .kr-login__card {
    padding: 32px 22px !important;
    border-radius: 16px !important;
  }
}

/* Any browser on a touch screen zooms the whole page when a field smaller
   than 16px takes focus, which leaves somebody scrolled sideways mid-login.
   16px is the threshold, so this is a fix rather than a preference. */
@media (max-width: 860px) {
  .kr-login input { font-size: 16px !important; }
  .kr-login button { min-height: 46px; }
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes shake {
  0%,100% { transform: translateX(0); }
  20%,60% { transform: translateX(-8px); }
  40%,80% { transform: translateX(8px); }
}
@keyframes spin {
  to { transform: rotate(360deg); }
}
.spin { animation: spin 0.7s linear infinite; }
input:focus {
  border-color: ${theme.primary} !important;
  background: #fff !important;
  box-shadow: 0 0 0 3px ${withAlpha(theme.primary, 0.18)};
}
button[type="submit"]:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px ${withAlpha(theme.primary, 0.45)};
}
@media (max-width: 768px) {
  .login-left { display: none !important; }
  .login-right { width: 100% !important; min-width: unset !important; }
}
`;

export default OpenCmsLogin;
